const ROOT = process.cwd();
const written = [], skipped = [], replaced = [];

for (const f of FILES) {
  const p = join(ROOT, f.path);
  const there = existsSync(p) ? readFileSync(p, "utf8") : null;

  if (there === f.body) { console.log("  " + f.path + " already done"); continue; }

  if (f.was === null) {
    if (there !== null) { skipped.push(f.path + " - already exists, and differs"); continue; }
  } else {
    if (there === null) { skipped.push(f.path + " - missing"); continue; }

    const bak = join(ROOT, "..", "zak-bak", f.path);
    const sum = (t) => createHash("md5").update(t, "utf8").digest("hex");
    const now = sum(there);

    if (now === f.was) {
      // Untouched. Keep a copy of it before writing over it.
      mkdirSync(dirname(bak), { recursive: true });
      copyFileSync(p, bak);
    } else if (existsSync(bak) && sum(readFileSync(bak, "utf8")) === f.was) {
      // Not the original - but the backup from an earlier run of this
      // script is, which means what is there now came from a run of this
      // same script. Safe to write over. The backup is left exactly as it
      // is so the real original is never lost, and what is there right now
      // is kept beside it as .prev, in case any of it was typed by hand.
      writeFileSync(bak + ".prev", there, "utf8");
      replaced.push(f.path);
    } else {
      skipped.push(f.path + " - changed since this script was built");
      continue;
    }
  }

  mkdirSync(dirname(p), { recursive: true });
  writeFileSync(p, f.body, "utf8");
  written.push(f.path);
}

console.log("");
for (const f of written) console.log("written  " + f);
for (const f of replaced) console.log("         " + f + " was already written by an earlier run - old copy kept as zak-bak\\...\\.prev");
for (const s of skipped) console.log("SKIPPED  " + s);
if (!written.length && !skipped.length) console.log("  nothing to change");

if (skipped.length) {
  console.log("");
  console.log("Those were left alone. Tell Claude which ones, before you build.");
} else {
  console.log("backup   ..\\zak-bak");
  console.log("");
  console.log("Next, one command at a time:");
  console.log("  npm run build");
  console.log("  git add -A");
  console.log("  git commit -m \"pay now inside the cod confirmation, and the rupee sign that was doubling up\"");
  console.log("  git push");
}
